s=s.replace('    progress = get_user_progress(http_request)\n\n    if not request.answers:', '    progress = get_user_progress(http_request)\n    rag_query = f"{request.interview_type} placement interview {request.difficulty} questions and evaluation guidance"\n    context, sources = await retrieve_context(http_request.state.firebase_user["uid"], rag_query)\n\n    if not request.answers:')
s=s.replace('            "- Do not provide answers."\n        )', '            "- Do not provide answers.\\n\\n"\n            f"Use this retrieved preparation context where relevant:\\n{context}"\n        )')
s=s.replace('        return {\n            "questions": questions\n        }', '        return {\n            "questions": questions, "rag_used": bool(context), "sources": sources\n        }')
